import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"24、【复】 震下坤上","description":"周易口诀义 - 24、【复】 震下坤上","frontmatter":{"title":"24、【复】 震下坤上","description":"周易口诀义 - 24、【复】 震下坤上"},"headers":[],"relativePath":"zh/classics/koujueyi/026.md","filePath":"zh/classics/koujueyi/026.md"}'),r={name:"zh/classics/koujueyi/026.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_24、【复】-震下坤上" tabindex="-1">24、【复】 震下坤上 <a class="header-anchor" href="#_24、【复】-震下坤上" aria-label="Permalink to “24、【复】 震下坤上”">​</a></h1><p>彖曰：「复，亨」。刚反动而以顺行，是以「出入无疾，朋来无咎」。「反复其道，七日来复」，天行也。「利有攸往」，刚长也。复，其见天地之心乎！</p><p>象曰：雷在地中，复，先王以至日闭关，商旅不行，后不省方。</p><p>初九，不远复，无祇悔，元吉。</p><p>象曰：「不远」之复，以修身也。</p><p>六二，休复，吉。</p><p>象曰：「休复」之吉，以下仁也。</p><p>六三，频复，厉无咎。</p><p>象曰：「频复」之厉，义无咎也。</p><p>六四，中行独复。</p><p>象曰：「中行独复」，以从道也。</p><p>六五，敦复，无悔。</p><p>象曰：「敦复无悔」，中以自考也。</p><p>上六，迷复，凶，有灾眚。用行师，终有大败，以其国君凶，至于十年不克征。</p><p>象曰：「速复」之凶，反君道也。</p><p>解读</p><p>复亨者，复是归本之名，静默为义，故老子云：「归根曰静，是谓复命」也。阳气反复，所以亨通，故曰「亨」也。「出入无疾，朋来无咎」者，出则刚长，入则阳复，理会其时，故「无疾」；朋谓众阳，以阳气渐长，众阳朋聚而来，故「无咎」。「反复其道，七日来复」者，反之与复，理会其宜，故曰「反复其道」；阳气灭绝之后，不过七日，阳复生来，故云「七日来复」。「利有攸往」，以阳气渐盛，阴柔乃消，故利有所往。象曰：雷在地中，复。以静默为义。雷本动物，今在地中，静默之象。「先王以至日闭关，商旅不行，后不省方」者，方，事也。先王于至之日，闭塞视听，不亲其事，商旅不行道路，在于君后，亦不省察四方之事也。</p><p>初九，不远复，无祇悔，元吉。祇，大也。最处复初，初知福之机，不为迷远，寻能求复，归于善道，故无大悔，而终获大吉也。</p><p>六二，休复，吉。处复之时，近初之阳，是亲仁善邻，既亲贤德之行，而获休美之吉。</p><p>六三，频复，厉，无咎。频，蹙之貌也。六三去复已远，虽胜上六之迷暗，犹可频蹙而复于危厉之中，而得无咎也。</p><p>六四，中行独复。独应于初，即是弃恶归善。处四阴之中，独得善道，故曰「中行独复」。</p><p>「六五，敦复，无悔」者，敦，厚也。处尊位，以敦厚之德，而能考成其行，故无悔而已也。</p><p>「上六，迷复，凶，有灾眚，用行师，终有大败，以其国君凶，至于十年不克征」者，上为最处复后，是迷暗而更求复也。以迷求复，去善既远，必致凶灾，故曰「迷复凶，有灾眚」。用此迷暗之人兴行师旅，终有大败。若用于其国内，即反违君道，故曰「用行师，终有大败」，以其国君凶也。纵使修身改悔，至于十年犹不能征进矣，故曰「至于十年不克征」。伤害曰灾，妖祥曰眚。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
